// The RESOURCE-PIPELINE paradigm's build-side seam. The app logo ships in a
// compiled-in GResource bundle (resources/lookit.gresource.xml -> lookit-resources.c,
// generated by glib-compile-resources). Declared extern "C" because that
// generated source compiles as C -- so its getter has C linkage and there's no
// generated header to include or keep in sync. (docs/resources-and-dialog-lifetime.md)
extern "C" GResource* lookit_resources_get_resource(void);

namespace lookit {

Glib::RefPtr<App> App::create() {
    log::init();   // area loggers up before anything logs
    return Glib::make_refptr_for_instance(new App());
}

App::App() : Gtk::Application("io.github.scott8420.Lookit", Gio::Application::Flags::HANDLES_OPEN) {
    // ── THE QUICK-SETTINGS-TILE STONE (docs/quick-settings-tile.md) ─────────
    // Two app actions are the whole contract with the outside:
    //   app.receive-text(s)    the tile's line, clipboard or selection
    //   app.receive-clipboard  read the clipboard here (desktop-entry action)
    // The tile calls them over D-Bus (org.freedesktop.Application.ActivateAction);
    // a closed app is STARTED by D-Bus first (the .service file
    // install-desktop.sh writes), then the action arrives. The command-line
    // options below are the same two actions by another door.
    add_main_option_entry(Gio::Application::OptionType::STRING, "send", 's',
                          "Open the file at TEXT (what the tile does)", "TEXT");
    add_main_option_entry(Gio::Application::OptionType::BOOL, "send-clipboard", '\0',
                          "Hand the clipboard's text to Lookit");
    signal_handle_local_options().connect(sigc::mem_fun(*this, &App::on_local_options), false);

    add_action_with_parameter("receive-text", Glib::Variant<Glib::ustring>::variant_type(),
        [this](const Glib::VariantBase& v) {
            ensure_shell().receive_text(
                Glib::VariantBase::cast_dynamic<Glib::Variant<Glib::ustring>>(v).get());
        });
    add_action("receive-clipboard", [this]() { ensure_shell().receive_clipboard(); });
}

// --send / --send-clipboard: register (which finds a running Lookit if there is
// one -- is_remote()), fire the action there or here, then carry on so
// activate presents the window. A plain launch returns -1 untouched.
int App::on_local_options(const Glib::RefPtr<Glib::VariantDict>& o) {
    Glib::ustring text;
    bool clip = false;
    const bool has_text = o->lookup_value("send", text);
    o->lookup_value("send-clipboard", clip);
    // s014.2: register here for every launch, so a Lookit that is running but
    // not answering (it holds the app's D-Bus name; GApplication's own register
    // gives up after D-Bus's 25 s with "Failed to register: Timeout was
    // reached" and quits) can't stop this one opening: say so, and run on our
    // own instead, unshared.
    if (!register_or_go_alone()) return 1;
    if (!has_text && !clip) return -1;
    if (auto lg = log::get(log::Area::App))
        lg->info("{} {}", has_text ? "--send" : "--send-clipboard",
                 is_remote() ? "-> the running Lookit" : "(this Lookit)");
    if (has_text) activate_action("receive-text", Glib::Variant<Glib::ustring>::create(text));
    else          activate_action("receive-clipboard");
    return -1;
}

bool App::register_or_go_alone() {
    try {
        if (register_application()) return true;
    } catch (const Glib::Error& e) {
        if (auto lg = log::get(log::Area::App)) lg->warn("register failed: {}", e.what());
        g_printerr("Lookit: another Lookit is running but not answering (%s).\n"
                   "Opening this one on its own. To close the stuck one: pkill -x lookit\n",
                   e.what());
    }
    set_flags(get_flags() | Gio::Application::Flags::NON_UNIQUE);
    try {
        if (register_application()) return true;
    } catch (const Glib::Error& e) {
        if (auto lg = log::get(log::Area::App)) lg->error("register failed again: {}", e.what());
    }
    return false;
}

// The SHORTCUT-REGISTRY paradigm's other consumer. Accelerators are an
// application-scope concern (they survive window construction order), so they
// bind here -- and they are driven from the pure core::shortcut_registry(), the
// same list ShortcutsDialog documents from. Register a shortcut once THERE and
// both the key and its advertised row follow; there is no second list to update
// and therefore nothing to drift. Doc-only rows (gestures) carry no action and
// are skipped -- they document without binding.
void App::on_startup() {
    Gtk::Application::on_startup();
    for (const auto& s : core::shortcut_registry()) {
        if (s.action.empty() || s.accels.empty()) continue;
        std::vector<Glib::ustring> accels(s.accels.begin(), s.accels.end());
        set_accels_for_action(s.action, accels);
    }
}

void App::on_activate() {
    ensure_shell().present();
}

// Files from outside: Files' "Open With", `lookit a.pdf`, D-Bus Open from the
// desktop entry. The first is shown; the rest go on the Recent list.
void App::on_open(const Gio::Application::type_vec_files& files, const Glib::ustring&) {
    auto& shell = ensure_shell();
    bool first = true;
    for (const auto& f : files) {
        const std::string p = f->get_path();
        if (p.empty()) continue;
        if (first) shell.open_path(p);
        first = false;
    }
    shell.present();
}

// One window, ever. Before the tile stone, every activate built a new Shell --
// harmless from the app grid, wrong once D-Bus can activate a running Lookit
// (each tile send would have opened another window). A closed window comes
// back: it left the application on close, so it is re-added.
Shell& App::ensure_shell() {
    if (m_shell) {
        if (!m_shell->get_application()) add_window(*m_shell);
        return *m_shell;
    }

    // ── ALWAYS DARK ─────────────────────────────────────────────────────────
    // Lookit wears the Rouster skin (Css.hpp): its own dark look, a gradient
    // per page -- Scott's colourful-utility family. GTK's dark variant is asked
    // for ahead of `new Shell()`, so menus, popovers and the file chooser
    // match. Appearance.* (follow the desktop) stays compiled, as in Fowler,
    // for a later "match the desktop" setting.
    if (auto settings = Gtk::Settings::get_default())
        settings->property_gtk_application_prefer_dark_theme() = true;

    // The app stylesheet (Css.hpp): the drawer tabs' hover-reveal, the panels.
    // APPLICATION priority so our named classes beat the theme's defaults.
    // s014: the stylesheet goes through core::tint_css with the remembered
    // base colour (LOOKIT_TINT=#rrggbb overrides it for one run, unsaved).
    // Teal, the default, is the design itself -- tint_css hands it back as is.
    if (auto display = Gdk::Display::get_default()) {
        m_css = Gtk::CssProvider::create();
        const char* env = std::getenv("LOOKIT_TINT");
        const std::string pick = env ? core::normalise_hex(env) : std::string();
        set_tint(pick.empty() ? core::load_tint(settings_file()) : pick, false);
        Gtk::StyleContext::add_provider_for_display(
            display, m_css, GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);
    }

    // Register the compiled-in bundle and point the icon theme at its icon
    // prefix, so set_icon_name("io.github.scott8420.Lookit") resolves out of the binary
    // and GTK recolours it to the theme foreground -- no icon on the user's disk.
    // NB: add_resource_path gets .../icons; GTK appends scalable/apps/ itself.
    g_resources_register(lookit_resources_get_resource());
    if (auto display = Gdk::Display::get_default()) {
        auto icons = Gtk::IconTheme::get_for_display(display);
        icons->add_resource_path("/io/github/scott8420/Lookit/icons");
    }

    m_shell = new Shell();       // lifetime owned by the application
    add_window(*m_shell);
    m_shell->build_ui();
    m_shell->show_tint(m_tint);
    if (auto lg = log::get(log::Area::App)) lg->info("Lookit window built");
    return *m_shell;
}

std::string App::settings_file() {
    return (std::filesystem::path(Glib::get_user_config_dir()) / "lookit" / "settings.json").string();
}

// Re-load the one provider: GTK restyles every widget in place, no rebuild.
void App::set_tint(const std::string& hex, bool remember) {
    const std::string h = core::normalise_hex(hex);
    if (h.empty() || !m_css) return;
    m_tint = h;
    m_css->load_from_data(core::tint_css(LOOKIT_CSS, h));
    if (remember) core::save_tint(settings_file(), h);
    if (m_shell) m_shell->show_tint(h);
    if (auto lg = log::get(log::Area::App))
        lg->info("tint {} ({}){}", h, core::tint_label(h), remember ? ", saved" : "");
}

}  // namespace lookit
